    <svg onClick={onClick} xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#6c757d' }}>
        <path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" />
        <path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" />
    </svg>
);
const DeleteIcon = ({ onClick }) => (
    <svg onClick={onClick} xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#dc3545' }}>
        <polyline points="3 6 5 6 21 6" />
        <path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" />
    </svg>
);
const SaveRowIcon = ({ onClick }) => (
    <svg onClick={onClick} xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ cursor: 'pointer', color: '#28a745' }}>
        <polyline points="20 6 9 17 4 12"></polyline>
    </svg>
);
const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', marginLeft: '8px' }}>
        <circle cx="12" cy="12" r="10" />
        <line x1="12" y1="16" x2="12" y2="12" />
        <line x1="12" y1="8" x2="12.01" y2="8" />
    </svg>
);

// --- Main Component ---
export default function PerDeliveryAllocationTab({ term, onAllocationChange }) {
    // --- State Management ---
    const [firstOfferingOfYear, setFirstOfferingOfYear] = useState('Yes');
    const [deliveries, setDeliveries] = useState([
        { id: 1, deliveryLocation: 'CTN', lecturer: 'Mary', weeklyLectureTime: 2, earlyCareerLoading: 'No' },
        { id: 2, deliveryLocation: 'PEN', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
        { id: 3, deliveryLocation: 'KWD', lecturer: 'Mary', weeklyLectureTime: 0, earlyCareerLoading: 'No' },
    ]);
    const [editingId, setEditingId] = useState(null);
    // State to hold validation errors
    const [errors, setErrors] = useState({});
    const [saveSuccess, setSaveSuccess] = useState(false);


    // --- Validation Logic ---
    const validate = () => {
        const newErrors = { global: [], rows: {} };
        const locations = new Set();

        // Rule: Must have at least one delivery
        if (deliveries.length === 0) {
            newErrors.global.push("You must have at least one delivery location added.");
        }

        // Rule: If 'First Offering' is 'Yes', at least one delivery must have lecture time > 0
        if (firstOfferingOfYear === 'Yes' && !deliveries.some(d => Number(d.weeklyLectureTime) > 0)) {
            newErrors.global.push("For a first offering, at least one delivery must have a weekly lecture time greater than 0.");
        }

        deliveries.forEach(d => {
            const rowErrors = {};
            // Rule: Delivery location cannot be empty
            if (!d.deliveryLocation.trim()) {
                rowErrors.deliveryLocation = "Delivery location cannot be empty.";
            }

            // Rule: Lecturer cannot be empty
            if (!d.lecturer.trim()) {
                rowErrors.lecturer = "Lecturer / Campus Coordinator cannot be empty.";
            }

            // Rule: Lecture time must be a non-negative number
            const lectureTime = Number(d.weeklyLectureTime);
            if (isNaN(lectureTime) || lectureTime < 0) {
                rowErrors.weeklyLectureTime = "Weekly lecture time must be a non-negative number.";
            }

            // Rule: Check for duplicate locations (case-insensitive)
            const locationKey = d.deliveryLocation.trim().toLowerCase();
            if (locationKey && locations.has(locationKey)) {
                rowErrors.deliveryLocation = "Duplicate delivery locations are not allowed.";
            }
            if (locationKey) {
                locations.add(locationKey);
            }

            if (Object.keys(rowErrors).length > 0) {
                newErrors.rows[d.id] = rowErrors;
            }
        });

        return newErrors;
    };


    // --- Calculation Logic ---
    const calculatedData = useMemo(() => {
        // ... (calculation logic remains the same)
        const termMultiplier = 1.0;
        const getEarlyCareerBonus = (loadingType) => {
            const map = { "Yes - materials provided": 0.02, "Yes - materials need major rewriting": 0.03, "Yes - no materials provided": 0.04 };
            return map[loadingType] || 0;
        };
        const individualAllocations = deliveries.map(d => 0.01 + ((Number(d.weeklyLectureTime) || 0) * termMultiplier * 0.01) + getEarlyCareerBonus(d.earlyCareerLoading));
        const sumOfIndividualAllocations = individualAllocations.reduce((sum, alloc) => sum + alloc, 0);
        let firstOfferingBonus = 0;
        if (firstOfferingOfYear === 'Yes' && deliveries.length > 0) {
            const maxLectureTime = Math.max(...deliveries.map(d => Number(d.weeklyLectureTime) || 0));
            firstOfferingBonus = 0.01 * termMultiplier * maxLectureTime;
        }
        const totalPerDeliveryAllocation = sumOfIndividualAllocations + firstOfferingBonus;
        return { total: totalPerDeliveryAllocation, individuals: individualAllocations };
    }, [deliveries, firstOfferingOfYear]);

    // --- Effect to notify parent ---
    useEffect(() => {
        if (onAllocationChange) {
            onAllocationChange(calculatedData.total);
        }
    }, [calculatedData.total, onAllocationChange]);

    // --- Event Handlers ---
    const handleAddDelivery = () => {
        setSaveSuccess(false); // Reset success message on change
        const newId = deliveries.length > 0 ? Math.max(...deliveries.map(d => d.id)) + 1 : 1;
        const newDelivery = { id: newId, deliveryLocation: '', lecturer: '', weeklyLectureTime: 0, earlyCareerLoading: 'No' };
        setDeliveries([...deliveries, newDelivery]);
        setEditingId(newId);
    };

    const handleDeleteDelivery = (idToDelete) => {
        setSaveSuccess(false);
        setDeliveries(deliveries.filter(d => d.id !== idToDelete));
    };

    const handleDeliveryChange = (id, field, value) => {
        setSaveSuccess(false);
        setDeliveries(deliveries.map(d => d.id === id ? { ...d, [field]: value } : d));
    };

    const handleSave = () => {
        setSaveSuccess(false);
        const validationErrors = validate();
        setErrors(validationErrors);

        if (validationErrors.global.length === 0 && Object.keys(validationErrors.rows).length === 0) {
            // If validation passes, proceed with save
            console.log("Validation successful. Saving data:", { firstOfferingOfYear, deliveries });
            setSaveSuccess(true);
            setEditingId(null); // Exit editing mode for all rows on successful save
            // Here you would typically send the data to an API
        } else {
            console.log("Validation failed:", validationErrors);
        }
    };

    // --- Render ---
    return (
        <div style={styles.container}>
            {/* Form Group and Select (unchanged) */}
            <div style={styles.formGroup}>
                <label style={styles.label} htmlFor="totalAllocation">Per-delivery Allocation <InfoIcon /></label>
                <input type="text" id="totalAllocation" readOnly style={styles.totalInput} value={`${(calculatedData.total * 100).toFixed(1)}%`} />
            </div>
            <div style={styles.formGroupWithBorder}>
                <label style={styles.label} htmlFor="firstOffering">First offering of the calendar year</label>
                <select id="firstOffering" style={styles.select} value={firstOfferingOfYear} onChange={(e) => setFirstOfferingOfYear(e.target.value)} >
                    <option value="Yes">Yes</option>
                    <option value="No">No</option>
                </select>
            </div>
            <div style={styles.tableActions}>
                 <button style={styles.addButton} onClick={handleAddDelivery}>+ Add</button>
            </div>

            <div style={styles.tableContainer}>
                {/* Table Header */}
                <div style={styles.tableHeader}>
                    <div style={{...styles.tableCell, flex: 0.5}}>Actions</div>
                    <div style={{...styles.tableCell, flex: 2}}>Delivery Location</div>
                    <div style={{...styles.tableCell, flex: 2}}>Lecturer / Coordinator</div>
                    <div style={{...styles.tableCell, flex: 2}}>Weekly lecture time (hrs)</div>
                    <div style={{...styles.tableCell, flex: 2.5}}>Early career loading</div>
                    <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}>Allocation</div>
                </div>

                {/* Table Body */}
                {deliveries.map((delivery, index) => {
                    const isEditing = editingId === delivery.id;
                    const rowErrors = errors.rows?.[delivery.id] || {};
                    return (
                        <div key={delivery.id} style={styles.tableRow}>
                            {/* Actions Cell */}
                            <div style={{...styles.tableCell, flex: 0.5, display: 'flex', gap: '8px' }}>
                                {isEditing ? <SaveRowIcon onClick={() => setEditingId(null)} /> : <EditIcon onClick={() => setEditingId(delivery.id)} />}
                                <DeleteIcon onClick={() => handleDeleteDelivery(delivery.id)} />
                            </div>

                            {/* Fields with Validation */}
                            <div style={{...styles.tableCell, flex: 2, flexDirection: 'column', alignItems: 'flex-start' }}>
                                <input type="text" style={{...styles.tableInput, ...(rowErrors.deliveryLocation && styles.errorInput)}} value={delivery.deliveryLocation} disabled={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'deliveryLocation', e.target.value)} />
                                {rowErrors.deliveryLocation && <span style={styles.errorMessage}>{rowErrors.deliveryLocation}</span>}
                            </div>
                            <div style={{...styles.tableCell, flex: 2, flexDirection: 'column', alignItems: 'flex-start' }}>
                                <input type="text" style={{...styles.tableInput, ...(rowErrors.lecturer && styles.errorInput)}} value={delivery.lecturer} disabled={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'lecturer', e.target.value)} />
                                {rowErrors.lecturer && <span style={styles.errorMessage}>{rowErrors.lecturer}</span>}
                            </div>
                            <div style={{...styles.tableCell, flex: 2, flexDirection: 'column', alignItems: 'flex-start' }}>
                                <input type="number" style={{...styles.tableInput, ...(rowErrors.weeklyLectureTime && styles.errorInput)}} value={delivery.weeklyLectureTime} min="0" disabled={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'weeklyLectureTime', e.target.value)} />
                                {rowErrors.weeklyLectureTime && <span style={styles.errorMessage}>{rowErrors.weeklyLectureTime}</span>}
                            </div>

                            {/* Unvalidated Fields */}
                            <div style={{...styles.tableCell, flex: 2.5}}>
                                <select style={styles.tableSelect} value={delivery.earlyCareerLoading} disabled={!isEditing} onChange={(e) => handleDeliveryChange(delivery.id, 'earlyCareerLoading', e.target.value)} >
                                    <option value="No">No</option>
                                    <option value="Yes - materials provided">Yes - materials provided</option>
                                    <option value="Yes - materials need major rewriting">Yes - materials need major rewriting</option>
                                    <option value="Yes - no materials provided">Yes - no materials provided</option>
                                </select>
                            </div>
                            <div style={{...styles.tableCell, flex: 1, justifyContent: 'flex-end'}}>
                                 <input type="text" readOnly style={{...styles.tableInput, ...styles.readOnlyInput}} value={`${(calculatedData.individuals[index] * 100).toFixed(1)}%`} />
                            </div>
                        </div>
                    );
                })}
            </div>

            <div style={styles.footer}>
                <button style={styles.saveButton} onClick={handleSave}>Save</button>
                {/* Global Error and Success Messages */}
                {errors.global && errors.global.length > 0 && (
                    <div style={styles.globalErrorContainer}>
                        {errors.global.map((err, i) => <div key={i}>{err}</div>)}
                    </div>
                )}
                {saveSuccess && <div style={styles.successMessage}>Data saved successfully!</div>}
            </div>
        </div>
    );
}

